SELECT id, goal_id, record_ym, target_saving, actual_saving,
       is_modified, created_at, updated_at
  FROM saving_record
 WHERE goal_id = #{goalId}
 ORDER BY record_ym DESC
 LIMIT #{limit}

SELECT id, goal_id, record_ym, target_saving, actual_saving,
       is_modified, created_at, updated_at
  FROM saving_record
 WHERE goal_id = #{goalId}
   AND record_ym = #{recordYm}
